(()=>{const cards=[...document.querySelectorAll('.proto-card')],preview=document.querySelector('.proto-preview .label'),drawer=document.createElement('aside');drawer.hidden=true;drawer.className='proto-drawer';drawer.innerHTML='<h2>Contact drawer</h2><label>Name<input data-demo-name value="Customer One"></label><label>Address<textarea data-demo-address>Analakely, near the market</textarea></label><button data-demo-save>Save demonstration</button><button data-demo-close>Close</button>';document.body.append(drawer);const refresh=()=>{preview.querySelector('strong').textContent=drawer.querySelector('[data-demo-name]').value};document.querySelector('[aria-label="Open new customer drawer"]').onclick=()=>drawer.hidden=false;drawer.querySelector('[data-demo-close]').onclick=()=>drawer.hidden=true;drawer.querySelector('[data-demo-save]').onclick=()=>{refresh();drawer.hidden=true};cards.forEach(card=>card.onclick=()=>{preview.querySelector('strong').textContent=card.querySelector('strong').textContent});const toggle=document.createElement('button');toggle.textContent='Toggle rail';toggle.className='button';toggle.setAttribute('aria-label','Toggle prototype rail');toggle.onclick=()=>document.body.classList.toggle('rail-expanded');document.querySelector('.proto-top').append(toggle);document.querySelector('.proto-preview h2').onclick=()=>preview.classList.toggle('enlarged')})();
